  retryAttempt += 1;
  state.nextRetryAt = Date.now() + delay;
  const generation = researchGeneration;
  retryTimer = setTimeout(() => {
    retryTimer = null;
    state.nextRetryAt = undefined;
    if (generation !== researchGeneration) return;
