        updatedAt: 1,
      });
    });
    const summary = await t
      .withIdentity({ subject: "alice" })
      .action(api.providerIdentity.getHostedUsage, { from: 100, to: 200 });

  // One-to-one identity bridge between a Better Auth product subject and the
  // DID restored by Twyne's ATProto OAuth client. The mutation enforces both
  // indexes as unique inside one Convex transaction.
  providerIdentities: defineTable({
    productSubject: v.string(),
    did: v.string(),
    verificationMethod: v.union(
      v.literal("legacy_atproto_browser_oauth"),
      v.literal("notorganic_pkce"),
    ),
    sessionVersion: v.number(),
    verifiedAt: v.number(),
    createdAt: v.number(),
    updatedAt: v.number(),
  })
    .index("by_productSubject", ["productSubject"])
    .index("by_did", ["did"]),

  /* One row per pre–Not Organic account: when it was told about the move and
   * when it was retired. Makes the notice send idempotent. */
  legacyAccountNotices: defineTable({
    userId: v.string(),
    email: v.string(),
    notifiedAt: v.optional(v.number()),
    retiredAt: v.optional(v.number()),
    JSON.stringify(claims),
  )}`;
  const signature = await crypto.subtle.sign(
    "Ed25519",
    await loadPrivateKey(privateKey),
    new TextEncoder().encode(signingInput),
  );
  return `${signingInput}.${base64url(new Uint8Array(signature))}`;
}

export async function exchangeProductAssertion(
  assertion: string,
  options: {
    readonly issuer?: string;
    readonly fetch?: typeof fetch;
    readonly dpop?: DpopKeyPair;
  } = {},
): Promise<NotOrganicAccessToken> {
  const issuer = (options.issuer ?? NOTORGANIC_DEFAULT_ISSUER).replace(
    /\/$/,
    "",
  );
  const dpop = options.dpop ?? (await createDpopKeyPair());
  const response = await (options.fetch ?? fetch)(
    `${issuer}/v1/auth/token/exchange`,
    {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify({
        assertion,
        dpop_jwk: dpop.publicJwk,
      }),
    },
  );
  if (!response.ok) {
    const detail = await response.text().catch(() => "");
    throw new Error(
      `Not Organic token exchange failed (${response.status}): ${detail.slice(0, 300)}`,
    );
  }
  const body = (await response.json()) as {
    access_token?: unknown;
    expires_in?: unknown;
    token_type?: unknown;
  };
  if (typeof body.access_token !== "string" || !body.access_token) {
    throw new Error("Not Organic token exchange returned no access_token");
  }
  return {
    accessToken: body.access_token,
    expiresIn:
      typeof body.expires_in === "number" ? body.expires_in : undefined,
    tokenType:
      typeof body.token_type === "string" ? body.token_type : undefined,
    dpop,
  };
  }),
  handler: async (ctx, { ownerId, ...args }) => {
    const caller = callerFromTokenIdentifier(ownerId);
    const strategy = args.strategy ?? "hosted";
    const brief = (args.brief ?? null) as ProjectBrief | null;
    const mode = dossierResearchMode(brief);
    const maxTargets = Math.max(1, Math.min(12, Math.floor(args.maxTargets ?? DEFAULT_TARGETS_PER_PASS)));
    if (strategy === "hosted") {
      // Keep the browser's ten-candidate scan; maxTargets caps confirmed output.
      const candidates = claimCandidates(args.draftText);
      if (!candidates.length) return { strategy, provider: "hosted", mode, targets: [], candidates };
      // System One runs in the default runtime; this module runs in Node.
      const result = await ctx.runAction(internal.systemOne.askAs, {
        ownerId,
        ...candidateRequest(candidates, mode),
      });
      if (!result.ok) {
        throw applicationError(
          result.error === "unconfigured" || result.error === "account not linked"
            ? "configuration_required"
            : result.error === "rate limited" ? "rate_limited" : "provider_unavailable",
        );
      }
      return { strategy, provider: "hosted", mode, targets: confirmedTargets(candidates, result).slice(0, maxTargets), candidates };
    }

    await consumeRateLimit(ctx, {
      action: "agent:feedback",
      identifier: caller.tokenIdentifier,
      ...RATE_LIMITS.agentFeedback,
    });
    const provider = await pickProvider(ctx, caller, "research-extract", "balanced");
    if (!provider) throw applicationError("configuration_required");
    try {
      const extracted = await generateWithSecondChance({
        ctx, caller, provider,
        feature: "research-extract",
        usageFeature: "research-extract",
        system: buildResearchExtractSystemPrompt(),
        prompt: buildResearchExtractUserPrompt({
          draftText: args.draftText,
          existingSources: args.existingSources ?? [],
          maxTargets,
          instructions: buildDossierResearchInstructions(brief),
        }),
        temperature: 0.2,
        functionId: "research_extract",
      }, (text) => text.trim() ? parseResearchTargets(text) : null);
      if (!extracted) throw applicationError("provider_unavailable");
      return { strategy, provider: extracted.provider.label, mode, targets: extracted.value.slice(0, maxTargets) };
    } finally {
      await flushArize();
    }
  },
});

