export function liveSearchConfigured(): boolean {
  const id = providerId();
  if (id === "notorganic") return notOrganicSearchSelected();
  if (id === "custom") return !!process.env.RESEARCH_SEARCH_URL?.trim();
  return !!researchApiKey();
